    if name!='sidecar' or cpu!='50m':raise ValueError('only approved sidecar request')
    metadata=source.get('metadata',{})
    if not all(isinstance(metadata.get(k),str) and metadata[k] for k in ('uid','resourceVersion')):raise ValueError('observed identity/version required')
    containers=source.get('spec',{}).get('template',{}).get('spec',{}).get('containers')
    if not isinstance(containers,list) or len([c for c in containers if c.get('name')==name])!=1:raise ValueError('unique target container required')
    out=copy.deepcopy(containers);target=next(c for c in out if c['name']==name)
    resources=target.setdefault('resources',{});requests=resources.setdefault('requests',{})
    existing=requests.get('cpu')
    if existing==cpu:return None
    if existing is not None:raise ValueError('unexpected existing CPU request; do not overwrite')
    requests['cpu']=cpu
    return {'metadata':{'uid':metadata['uid'],'resourceVersion':metadata['resourceVersion']},'spec':{'template':{'spec':{'containers':out}}}}
